import { code } from '../../code.ts';
import type { IosValues } from '../values.ts';

// The path of the file in plugins/ios.
export const path = (v: IosValues) => `${v.id}/BUILD.bazel`;

export default (v: IosValues) => code`
# Generated by plugins/tools/generate.ts from plugins/plugins/${v.id}/plugin.json; do not edit.
load("@rules_cc//cc:defs.bzl", "objc_library")
load("//bazel:flags.bzl", "CPP_FLAGS")

# Registers the ${v.displayName} plugin. It links the plugin's own library, which the SDK may link as well, so the
# plugin's code exists once in an app.
objc_library(
    name = "${v.id}",
    srcs = ["src/${v.product}.mm"],
    hdrs = ["include/${v.product}/${v.product}.h"],
    copts = CPP_FLAGS,
    includes = ["include"],
    module_name = "${v.product}",
${v.compatible}
    visibility = ["//visibility:public"],
    deps = ["//plugins/plugins/${v.id}"],
)
${v.demo}`;
